 net=[r[3]-.008 for r in rs];stress=[r[3]-.012 for r in rs];gross=[r[3] for r in rs];days=collections.defaultdict(list);own=collections.defaultdict(list);fair=collections.defaultdict(list);perstock=collections.defaultdict(float)
